/**
 * Maps to runtime APIs from @sanity/functions
 * @param outcomes - array of outcomes from the batch execution, each outcome should have a status and result or error
 * @param reason - a string indicating the reason for the batch result, e.g., 'ALL_COMPLETED' or 'FAILED'
 */
export const getBatchResults = (outcomes, reason) => {
  /**
   * Returns an array of all outcomes, regardless of their status.
   */
  const all = outcomes.map((outcome) => ({...outcome}))

  /**
   * Returns an array of outcomes that have failed (status 'FAILED').
   */
  const failed = () =>
    all.filter((outcome) => outcome.error !== undefined && outcome.status === 'FAILED')

  /**
   * Returns an array of outcomes that have succeeded (status 'SUCCEEDED').
   */
  const succeeded = () => all.filter((outcome) => outcome.status === 'SUCCEEDED')

  /**
   * Returns an array of outcomes that are still in progress (status 'STARTED').
   */
  const started = () => all.filter((outcome) => outcome.status === 'STARTED')

  /**
   * Returns the count of successful outcomes (status 'SUCCEEDED')
   */
  const successCount = all.filter((item) => item.status === 'SUCCEEDED').length

  /**
   * Returns the count of failed outcomes (status 'FAILED')
   */
  const failureCount = all.filter((item) => item.status === 'FAILED').length

  /**
   * Returns an array of results from successful outcomes (status 'SUCCEEDED').
   */
  const getResults = () => succeeded().map((item) => item.result)

  /**
   * Returns an array of errors from failed outcomes (status 'FAILED').
   */
  const getErrors = () => failed().map((item) => item.error)

  /**
   * Throws the first error found in the failed outcomes (status 'FAILED').
   */
  const throwIfError = () => {
    const failure = all.find((outcome) => outcome.status === 'FAILED')
    if (failure?.error) {
      throw failure.error
    }
  }

  return {
    all,
    status: failureCount > 0 ? 'FAILED' : 'SUCCEEDED',
    hasFailure: failureCount > 0,
    failed,
    succeeded,
    started,
    reason,
    successCount,
    failureCount,
    startedCount: started().length,
    totalCount: all.length,
    getResults,
    getErrors,
    throwIfError,
  }
}
